{
  "families": [
    {
      "family": "iterative",
      "ranges": [
        {"param": "data_width", "low": 8, "high": 24, "choices": null},
        {"param": "n_iter", "low": 8, "high": 24, "choices": null},
        {"param": "angle_guard", "low": -2, "high": 4, "choices": null},
        {"param": "frac_guard", "low": 0, "high": 4, "choices": null},
        {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]}
      ],
      "budget_share": 0.65,
      "why": "Smallest area per (W,N): one shared adder/barrel-shifter datapath reused over N+3 cycles, and the 1 MSPS floor is easily met (only needs Fmax >= N+3 MHz). Majority of the budget to locate the min-area feasible corner and trace the area/accuracy front."
    },
    {
      "family": "unrolled_k",
      "ranges": [
        {"param": "data_width", "low": 8, "high": 20, "choices": null},
        {"param": "n_iter", "low": 8, "high": 20, "choices": null},
        {"param": "angle_guard", "low": -2, "high": 4, "choices": null},
        {"param": "frac_guard", "low": 0, "high": 4, "choices": null},
        {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]},
        {"param": "k", "low": 2, "high": 4, "choices": null}
      ],
      "budget_share": 0.15,
      "why": "Same accuracy surface as iterative but k chained micro-rotations per cycle, so expected to be dominated on area; included to verify that and to catch any case where a shorter critical path changes the area ranking."
    },
    {
      "family": "pipelined_m",
      "ranges": [
        {"param": "data_width", "low": 8, "high": 20, "choices": null},
        {"param": "n_iter", "low": 8, "high": 20, "choices": null},
        {"param": "angle_guard", "low": -2, "high": 4, "choices": null},
        {"param": "frac_guard", "low": 0, "high": 4, "choices": null},
        {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]},
        {"param": "m", "low": 4, "high": 8, "choices": null}
      ],
      "budget_share": 0.15,
      "why": "Register-every-m variant gives 1 result/cycle but ceil(N/m) full-width pipeline registers, so likely dominated on area; small share to confirm and to cover the throughput-rich end of the front."
    },
    {
      "family": "pipelined",
      "ranges": [
        {"param": "data_width", "low": 8, "high": 20, "choices": null},
        {"param": "n_iter", "low": 8, "high": 20, "choices": null},
        {"param": "angle_guard", "low": -2, "high": 4, "choices": null},
        {"param": "frac_guard", "low": 0, "high": 4, "choices": null},
        {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]}
      ],
      "budget_share": 0.05,
      "why": "Fully pipelined: 1 result/cycle but N full-width register stages, the largest area of all families; tiny share only to confirm it is dominated (same accuracy, more area)."
    }
  ],
  "rationale": "The spec is area-dominated: the only hard accuracy requirement is max_abs_err <= 2^-10, which needs roughly W >= 11 and N >= 11, while the 1 MSPS throughput floor is trivially met by every family (iterative needs only Fmax >= N+3 MHz). Since accuracy depends only on (data_width, n_iter, angle_guard, frac_guard, rounding), all families share one accuracy surface, so the Pareto front over (area, accuracy_bits) will be populated by whichever family has the smallest area for a given (W,N) - almost certainly `iterative`. Round 1 therefore gives `iterative` the bulk of the budget over a wide W/N box (8..24) that brackets the feasible boundary and extends toward the 40000 um^2 HV reference, with smaller shares on `unrolled_k`, `pipelined_m` and `pipelined` to confirm they are dominated and to catch any surprise in the area model."
}
